import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BJN3HbfX.js";const u=JSON.parse('{"title":"Agent Skill","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent-skill.md","filePath":"guide/agent-skill.md"}'),i={name:"guide/agent-skill.md"};function r(l,e,n,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="agent-skill" tabindex="-1">Agent Skill <a class="header-anchor" href="#agent-skill" aria-label="Permalink to &quot;Agent Skill&quot;">​</a></h1><p>The <strong>jevwright-test-files</strong> Agent Skill teaches your coding agent, such as Claude Code, Codex, Cursor, GitHub Copilot or Antigravity, to write Jevwright test files in our syntax. With it, you describe a test in your words and the agent writes a valid file, using selectors where your page has them, descriptions where it does not, and Variables for your URL and secrets.</p><p>The skill is a folder in the open <a href="https://agentskills.io" target="_blank" rel="noreferrer">Agent Skills</a> format: a <code>SKILL.md</code> file with the rules, a longer reference, and example files that we check against Jevwright&#39;s Syntax Analyzer on every change, so the skill always matches the syntax.</p><p><a href="https://github.com/yike2/Jevwright/tree/main/skills/jevwright-test-files" target="_blank" rel="noreferrer">Browse the skill on GitHub</a></p><h2 id="what-it-covers" tabindex="-1">What it covers <a class="header-anchor" href="#what-it-covers" aria-label="Permalink to &quot;What it covers&quot;">​</a></h2><ul><li>The shape of a test file, every action and check, and every field.</li><li>When to use a <code>selector</code>, a <code>target</code>, or both, and a Playwright <code>assert</code> or a <code>statement</code>.</li><li><code>{{VARIABLES}}</code>, which come from your Project&#39;s Variables in the web workspace.</li><li><code>headers</code>, <code>cookies</code>, <code>localStorage</code> and <code>sessionStorage</code>, to start a test already signed in.</li><li>Every diagnostic code, and what a failed step&#39;s reason means.</li><li>Never using the planning keys of other tools, such as <code>ai</code> or <code>aiAct</code>, which Jevwright refuses.</li></ul><p>For anything the skill leaves out, it points the agent at this guide and at the <a href="https://github.com/yike2/Jevwright/blob/main/docs/tech/syntax-analyzer.md" target="_blank" rel="noreferrer">syntax design document</a> on GitHub.</p><h2 id="install-it" tabindex="-1">Install it <a class="header-anchor" href="#install-it" aria-label="Permalink to &quot;Install it&quot;">​</a></h2><ol><li>Download the folder <code>skills/jevwright-test-files</code> from the <a href="https://github.com/yike2/Jevwright/tree/main/skills/jevwright-test-files" target="_blank" rel="noreferrer">repository</a>, for example by downloading the repository as a ZIP file and taking that folder out of it.</li><li>Copy the whole folder, keeping its name, into the skills folder your agent reads, in the project you write tests in:</li></ol><table tabindex="0"><thead><tr><th>Agent</th><th>Folder in your project</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>.claude/skills/jevwright-test-files/</code></td></tr><tr><td>GitHub Copilot in VS Code</td><td><code>.github/skills/jevwright-test-files/</code></td></tr><tr><td>Codex, Cursor, Antigravity, and other agents that support Agent Skills</td><td><code>.agents/skills/jevwright-test-files/</code></td></tr></tbody></table><p>Most agents can also load skills from a folder in your home directory, for every project; see your agent&#39;s documentation for its exact location.</p><ol start="3"><li>Start a new session of your agent. It lists its skills at the start and uses this one when you ask for a Jevwright test.</li></ol><h2 id="use-it" tabindex="-1">Use it <a class="header-anchor" href="#use-it" aria-label="Permalink to &quot;Use it&quot;">​</a></h2><p>Ask in your own words, and say what the agent needs to know:</p><blockquote><p>Write a Jevwright test for <a href="https://shop.example.com" target="_blank" rel="noreferrer">https://shop.example.com</a>: sign in as the test user (password in the TEST_PASSWORD Variable), add the first product to the cart, and check that the cart shows one item.</p></blockquote><p>Then:</p><ol><li>Upload the file to the web workspace, and set the Variables the agent names on the Project.</li><li>If the <strong>Debug console</strong> lists problems, copy its lines and paste them back to the agent: &quot;Fix these Jevwright diagnostics&quot;. It fixes every one and returns the corrected file.</li><li>Run the file. If a step fails, paste its reason to the agent with what the step&#39;s screenshot shows.</li></ol><p>The <a href="./workflow.html">General workflow</a> walks through these steps, with what can go wrong at each one.</p>',18)])])}const p=t(i,[["render",r]]);export{u as __pageData,p as default};
